-- Eredivisie and Bundesliga clubs. Re-runnable: existing data not erased.
on conflict (club) do update set logo_url=coalesce(excluded.logo_url,public.matchtrip_club_media.logo_url),club_source_url=coalesce(excluded.club_source_url,public.matchtrip_club_media.club_source_url),stadium=coalesce(excluded.stadium,public.matchtrip_club_media.stadium),stadium_image_url=coalesce(excluded.stadium_image_url,public.matchtrip_club_media.stadium_image_url),stadium_source_url=coalesce(excluded.stadium_source_url,public.matchtrip_club_media.stadium_source_url),stadium_official_url=coalesce(excluded.stadium_official_url,public.matchtrip_club_media.stadium_official_url),verified_at=coalesce(excluded.verified_at,public.matchtrip_club_media.verified_at);
